<script setup>
import { computed, reactive, ref, watch } from 'vue'; import MButton from '../../../components/mds/MButton.vue'; import MDialog from '../../../components/mds/MDialog.vue'; import MInput from '../../../components/mds/MInput.vue'; import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue'; import MSelect from '../../../components/mds/MSelect.vue'; import MTextarea from '../../../components/mds/MTextarea.vue'; import { PARTNER_TYPES, partnerCreateDraft, partnerTypeMeta, toPartnerCreatePayload, validatePartnerCreateDraft } from '../domain/partner-list.mjs';
const props=defineProps({type:String,saving:Boolean,serverError:String,safeAreaStyle:{type:Object,default:()=>({})}});const emit=defineEmits(['cancel','save']);const draft=reactive(partnerCreateDraft(props.type));const errors=reactive({});const discard=ref(false);const initial=ref(JSON.stringify(draft));watch(()=>props.type,(type)=>{Object.assign(draft,partnerCreateDraft(type));initial.value=JSON.stringify(draft);});const tiers=['','Chiến lược','Quan trọng','Phát triển','Theo dõi'].map((value)=>({value,label:value||'Chưa xếp cấp độ'}));const adminLevels=['','Trung ương','Tỉnh/Thành phố','Quận/Huyện','Khác'].map((value)=>({value,label:value||'Chưa chọn'}));const dirty=computed(()=>JSON.stringify(draft)!==initial.value);function validate(){const next=validatePartnerCreateDraft(draft);Object.keys(errors).forEach((key)=>delete errors[key]);Object.assign(errors,next);return next;}function cancel(){if(!props.saving){if(dirty.value)discard.value=true;else emit('cancel');}}function submit(){if(!Object.keys(validate()).length)emit('save',toPartnerCreatePayload(draft));}
</script>
<template><section class="mds-mobile-app flex h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)]" :style="safeAreaStyle"><MMobileTopBar :title="`Thêm ${partnerTypeMeta(draft.org_type).label.toLowerCase()}`" @back="cancel"><template #actions><MButton variant="link" :disabled="saving" @click="cancel">Hủy</MButton></template></MMobileTopBar><form class="flex min-h-0 flex-1 flex-col" novalidate @submit.prevent="submit"><main class="min-h-0 flex-1 overflow-y-auto"><p class="mds-mobile-gutter-x border-b border-[var(--mds-border-light)] py-3 text-[13px] text-[var(--mds-text-secondary)]">Thông tin tài chính và tệp được bổ sung tại hồ sơ sau khi tạo.</p><div class="mds-mobile-gutter-x space-y-4 py-4"><label><span class="mb-1.5 block text-[13px] font-medium">Tên cơ quan <span class="text-[var(--mds-danger)]">*</span></span><MInput v-model="draft.name" :error="errors.name" :disabled="saving"/></label><label><span class="mb-1.5 block text-[13px] font-medium">Nhóm cơ quan <span class="text-[var(--mds-danger)]">*</span></span><MSelect v-model="draft.org_type" :options="PARTNER_TYPES" :error="errors.org_type" :disabled="saving"/></label><label><span class="mb-1.5 block text-[13px] font-medium">Cấp độ quan hệ</span><MSelect v-model="draft.tier" :options="tiers" :disabled="saving"/></label><label><span class="mb-1.5 block text-[13px] font-medium">Ngày thành lập</span><MInput v-model="draft.founded_date" type="date" :disabled="saving"/></label><label><span class="mb-1.5 block text-[13px] font-medium">Đơn vị chủ quản</span><MInput v-model="draft.parent_org" :disabled="saving"/></label><label><span class="mb-1.5 block text-[13px] font-medium">Website</span><MInput v-model="draft.website" type="url" :disabled="saving"/></label><label><span class="mb-1.5 block text-[13px] font-medium">Địa chỉ</span><MInput v-model="draft.address" :disabled="saving"/></label><template v-if="draft.org_type==='association'"><label><span class="mb-1.5 block text-[13px] font-medium">Tên viết tắt</span><MInput v-model="draft.abbreviation" :disabled="saving"/></label><label><span class="mb-1.5 block text-[13px] font-medium">Lĩnh vực hoạt động</span><MInput v-model="draft.field_area" :disabled="saving"/></label></template><template v-if="draft.org_type==='gov'"><label><span class="mb-1.5 block text-[13px] font-medium">Cấp quản lý</span><MSelect v-model="draft.admin_level" :options="adminLevels" :disabled="saving"/></label><label><span class="mb-1.5 block text-[13px] font-medium">Khối cơ quan</span><MInput v-model="draft.agency_block" :disabled="saving"/></label></template><label><span class="mb-1.5 block text-[13px] font-medium">Ghi chú</span><MTextarea v-model="draft.note" :rows="3" maxlength="2000" :disabled="saving"/></label><p v-if="serverError" role="alert" class="rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{ serverError }}</p></div></main><footer class="shrink-0 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-4 pb-[calc(12px+var(--mds-mobile-safe-bottom))] pt-3"><MButton variant="primary" class="w-full" :loading="saving" :disabled="saving" @click="submit">Tạo cơ quan</MButton></footer></form><MDialog v-model="discard" title="Bỏ cơ quan mới?" type="danger" confirm-text="Bỏ thay đổi" @confirm="emit('cancel')"><p>Thông tin chưa lưu sẽ không được giữ lại.</p></MDialog></section></template>
